#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


run_wizard() {

TOTAL_STAGES=8

cd "$(dirname "$0")/.."
WORKER=pacafe-cart-showroom
BUCKET=pacafe-cart-showroom-media

banner "Deploy the Cart Showroom to Cloudflare"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare: sign in"
say "Deploying needs a wrangler login that can write Workers scripts."
who=$(npx wrangler whoami 2>/dev/null || true)
if grep -q 'workers_scripts (write)' <<<"$who"; then
  printf '  %s✓%s already signed in with deploy permission\n' "$GREEN" "$RESET"
  grep -E 'logged in|Account' <<<"$who" | grep -v 'Account Name' | sed 's/^/  /' || true
  confirm "Deploy to this account?" || { warn "run 'npx wrangler logout' then re-run this wizard to switch accounts"; exit 1; }
else
  step "A browser tab opens. Sign in to Cloudflare and click Allow."
  npx wrangler login
  who=$(npx wrangler whoami 2>/dev/null || true)
  grep -q 'workers_scripts (write)' <<<"$who" || { warn "this login still can't deploy Workers; re-run after fixing it"; exit 1; }
fi

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "R2: the media bucket"
say "Intro videos and the owner's sprite are stored in the R2 bucket $BUCKET."
if npx wrangler r2 bucket info "$BUCKET" >/dev/null 2>&1; then
  printf '  %s✓%s bucket %s already exists\n' "$GREEN" "$RESET" "$BUCKET"
elif confirm "Create bucket $BUCKET now?"; then
  if ! npx wrangler r2 bucket create "$BUCKET"; then
    warn "R2 may not be turned on for this account yet."
    open_url "https://dash.cloudflare.com/?to=/:account/r2/overview"
    step "If the dashboard asks you to enable R2 (it can ask for a payment method), do that."
    pause "Then press Enter to try again."
    npx wrangler r2 bucket create "$BUCKET"
  fi
else
  warn "the deploy fails without the bucket"; exit 1
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Owner key"
say "CART_MCP_TOKEN is the owner key. The room, Muse Code over /mcp, and the promo runner all send it."
CART_MCP_TOKEN=$(_existing CART_MCP_TOKEN || true)
if [[ -n "$CART_MCP_TOKEN" ]]; then
  note "found one in $ENV_FILE (ending …${CART_MCP_TOKEN: -4})."
  if confirm "Make a new one instead? Anything holding the old key stops working"; then CART_MCP_TOKEN=""; fi
fi
[[ -n "$CART_MCP_TOKEN" ]] || CART_MCP_TOKEN=$(openssl rand -hex 24)
write_env CART_MCP_TOKEN "$CART_MCP_TOKEN"
note "it is uploaded with the deploy in stage 6 and never printed."

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Meta Model API: house key"
say "The clerk, the intro storyboard and the owner sprite call the Meta Model API with the house key."
open_url "https://dev.meta.ai"
step "Sign in and open your API keys. Create a key for this showroom and copy it."
note "Leave it empty to deploy without one. The clerk then says it needs a key."
ask_secret META_API_KEY "Paste the API key:" || META_API_KEY=""
if [[ -n "$META_API_KEY" ]]; then
  step "In the API docs or quickstart, copy the base URL that /chat/completions hangs off (it ends in /v1)."
  while :; do
    ask META_API_BASE_URL "Paste the base URL:" || META_API_BASE_URL=""
    [[ "$META_API_BASE_URL" =~ ^https://[^[:space:]]+$ ]] && break
    warn "that doesn't look like an https:// URL; try again"
  done
  write_env META_API_KEY "$META_API_KEY"
  write_env META_API_BASE_URL "$META_API_BASE_URL"
else
  META_API_BASE_URL=""
  SKIPPED+=("Meta API key: re-run this wizard with one before judges try the clerk")
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Daily spend cap"
say "The house key spends at most CLERK_DAILY_USD dollars a day (UTC). Past it, the clerk asks for the visitor's own key."
cap=$(_existing CLERK_DAILY_USD || echo 2)
while :; do
  ask CLERK_DAILY_USD "Dollars per day [$cap]:" || CLERK_DAILY_USD=""
  CLERK_DAILY_USD="${CLERK_DAILY_USD:-$cap}"
  [[ "$CLERK_DAILY_USD" =~ ^[0-9]+(\.[0-9]+)?$ ]] && break
  warn "a plain number, like 2 or 5"
done
write_env CLERK_DAILY_USD "$CLERK_DAILY_USD"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Build and deploy"
say "This builds the room and uploads Worker $WORKER with its secrets. Visitors see it at once."
confirm "Deploy now?" || { warn "nothing deployed; re-run when ready"; exit 1; }
npm run build
SECRETS_DIR=$(mktemp -d); trap 'rm -rf "$SECRETS_DIR"' EXIT
( umask 077
  CART_MCP_TOKEN="$CART_MCP_TOKEN" META_API_KEY="$META_API_KEY" META_API_BASE_URL="$META_API_BASE_URL" node -e '
    const names = ["CART_MCP_TOKEN", "META_API_KEY", "META_API_BASE_URL"];
    process.stdout.write(JSON.stringify(Object.fromEntries(names.filter(n => process.env[n]).map(n => [n, process.env[n]]))));
  ' > "$SECRETS_DIR/secrets.json" )
npx wrangler deploy --env="" --secrets-file "$SECRETS_DIR/secrets.json" --var "CLERK_DAILY_USD:$CLERK_DAILY_USD"
rm -rf "$SECRETS_DIR"
printf '\n'
step "wrangler printed the live URL above (https://$WORKER.<your-subdomain>.workers.dev)."
while :; do
  ask SHOWROOM_URL "Paste that URL:" || SHOWROOM_URL=""
  SHOWROOM_URL="${SHOWROOM_URL%/}"
  [[ "$SHOWROOM_URL" =~ ^https://[^[:space:]/]+$ ]] && break
  warn "just the https:// origin, with no path"
done
write_env SHOWROOM_URL "$SHOWROOM_URL"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Smoke test"
say "Checking $SHOWROOM_URL from here."
check() { # check "label" expected-status curl-args...
  local label="$1" want="$2" got; shift 2
  got=$(curl -s -o /dev/null -w '%{http_code}' --max-time 20 "$@") || got=000
  if [[ "$got" == "$want" ]]; then printf '  %s✓%s %s (%s)\n' "$GREEN" "$RESET" "$label" "$got"
  else warn "$label: wanted $want, got $got"; SKIPPED+=("smoke test failed: $label (got $got)"); fi
}
owner() { printf 'Authorization: Bearer %s\n' "$CART_MCP_TOKEN"; }
check "room page loads" 200 "$SHOWROOM_URL/"
check "cart refuses a stranger" 401 "$SHOWROOM_URL/api/cart"
check "cart opens with the owner key" 200 -H @- "$SHOWROOM_URL/api/cart" < <(owner)
if [[ -n "$META_API_KEY" ]]; then
  cast=$(curl -s --max-time 20 -H @- "$SHOWROOM_URL/api/cast" < <(owner) || true)
  if grep -q '"available":true' <<<"$cast"; then
    printf '  %s✓%s house key is set (sprite generation available)\n' "$GREEN" "$RESET"
  else
    warn "the worker doesn't see the Meta key"; SKIPPED+=("smoke test failed: Meta key not visible to the worker")
  fi
fi
printf '\n'
if command -v pbcopy >/dev/null 2>&1; then
  printf '%s' "$CART_MCP_TOKEN" | pbcopy
  say "The owner key is on your clipboard."
else
  say "The owner key is CART_MCP_TOKEN in $ENV_FILE."
fi
open_url "$SHOWROOM_URL"
step "Paste the key when the room asks for it. The cart starts empty."
step "Press Talk to Muse and ask \"What is on my shelf?\" to try the clerk on the house key."
pause "Press Enter when the room works."

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Record the URL in SUBMISSION.md"
line="**Hosted demo.** $SHOWROOM_URL"
if grep -qxF "$line" SUBMISSION.md; then
  printf '  %s✓%s SUBMISSION.md already points at %s\n' "$GREEN" "$RESET" "$SHOWROOM_URL"
elif confirm "Put \"$line\" under the title of SUBMISSION.md?"; then
  tmp=$(mktemp)
  awk -v line="$line" '
    skip && /^$/ { skip = 0; next }
    { skip = 0 }
    /^\*\*Hosted demo\.\*\*/ { skip = 1; next }
    { print }
    !done && NR > 1 && /^$/ { print line; print ""; done = 1 }
  ' SUBMISSION.md > "$tmp"
  cat "$tmp" > SUBMISSION.md; rm -f "$tmp"
  printf '  %s✓ wrote%s SUBMISSION.md (not committed)\n' "$GREEN" "$RESET"
fi
# ──────────────────────────────────────────────────────────────────────────

finish
note "Next:"
note "  - render intro videos against the live room:  npm run runner -- --origin $SHOWROOM_URL"
note "  - point Muse Code at $SHOWROOM_URL/mcp with the owner key as a Bearer token"
note "  - redeploy after code changes by re-running this wizard (it keeps every value)"
printf '\n'
}

run_wizard "$@"; exit
